{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.12","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[{"sourceType":"competition","sourceId":128431,"databundleVersionId":15477148},{"sourceType":"datasetVersion","sourceId":15083066,"datasetId":9619129,"databundleVersionId":15966527},{"sourceType":"datasetVersion","sourceId":15083112,"datasetId":9656889,"databundleVersionId":15966578},{"sourceType":"datasetVersion","sourceId":15270978,"datasetId":9768651,"databundleVersionId":16170957},{"sourceType":"modelInstanceVersion","sourceId":792804,"databundleVersionId":16174849,"modelInstanceId":604940,"modelId":617017}],"dockerImageVersionId":31287,"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code] {\"jupyter\":{\"outputs_hidden\":false},\"execution\":{\"iopub.status.busy\":\"2026-03-19T12:24:38.447812Z\",\"iopub.execute_input\":\"2026-03-19T12:24:38.448139Z\",\"iopub.status.idle\":\"2026-03-19T12:25:07.843454Z\",\"shell.execute_reply.started\":\"2026-03-19T12:24:38.448113Z\",\"shell.execute_reply\":\"2026-03-19T12:25:07.842041Z\"}}\nimport os\nimport glob\nimport random\nimport warnings\nimport multiprocessing\nimport pandas as pd\nimport numpy as np\nimport librosa\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nimport pytorch_lightning as pl\nimport torchaudio.transforms as T\nfrom torch.utils.data import Dataset, DataLoader\nfrom pytorch_lightning.callbacks import EarlyStopping, ModelCheckpoint, StochasticWeightAveraging\nfrom pytorch_lightning.loggers import WandbLogger\nfrom torchmetrics.classification import MulticlassF1Score\nfrom transformers import get_cosine_schedule_with_warmup\nfrom pathlib import Path\nfrom tqdm import tqdm\nimport concurrent.futures\n\nos.system('uv pip install --upgrade wandb')\nimport wandb\n\n# ==========================================\n# 0. CONFIGURATION & SETUP\n# ==========================================\nwarnings.filterwarnings('ignore')\npl.seed_everything(14, workers=True)\n\n# Toggle these as needed\nRUN_GENERATION = False \nRUN_TRAINING = False\nRUN_INFERENCE = True\n\nCONFIG = {\n    \"project_name\": \"23f2001635-t12026\",\n    \"experiment_name\": \"cnn_scratch_mashup\",\n    \"data_root\": \"/kaggle/input/competitions/jan-2026-dl-gen-ai-project/messy_mashup\",\n    \n    # ⚠️ MEGASET PATHS (Reusing your exact generated data) ⚠️\n    \"synthetic_data_dir\": \"/kaggle/input/datasets/harshitsahu01/dataset-for-ast-v1/processed_data_ast\",\n    \"pseudo_labeled_dataset\": \"/kaggle/input/datasets/harshitsahu01/messymashup-pseudolabeled-audios/pseudo_labels\", \n    \"pure_mashups_dir\": \"/kaggle/input/datasets/harshitsahu01/pure-mashups-dlgenai/pure_mashups\", \n\n    \"best_checkpoint\": \"/kaggle/input/models/harshitsahu01/scratchcnn-messymashup/pytorch/v1/1/checkpoints_cnn/best-cnn.ckpt\",\n    \"save_dir\": \"/kaggle/working/pure_mashups\", \n    \n    # CNNs trained from scratch need a higher LR than fine-tuned models\n    \"learning_rate\": 1e-3,         \n    \"weight_decay\": 1e-4,\n    \"label_smoothing\": 0.05, \n    \n    \"batch_size\": 32,        # CNNs use less memory, bumped batch size up slightly\n    \"accumulate_grad\": 2,    # Effective batch size = 64\n    \"num_epochs\": 20,        # Scratch models take slightly longer to converge\n    \"patience\": 10, \n    \"num_classes\": 10,\n    \"sample_rate\": 16000,\n    \"ast_frames\": 1024,      # Keeping 1024 frames so we can reuse AST data!\n    \"duration\": 30,\n    \"num_workers\": multiprocessing.cpu_count()\n}\n\nGENRES = [\"blues\", \"classical\", \"country\", \"disco\", \"hiphop\", \n          \"jazz\", \"metal\", \"pop\", \"reggae\", \"rock\"]\nGENRE_TO_IDX = {g: i for i, g in enumerate(GENRES)}\nIDX_TO_GENRE = {i: g for i, g in enumerate(GENRES)}\n\n# Reusing AST normalization stats so the dataset loads perfectly\nAST_MEAN = -4.2677393\nAST_STD = 4.5689974\n\nif RUN_TRAINING:\n    from kaggle_secrets import UserSecretsClient\n    try:\n        user_secrets = UserSecretsClient()\n        wandb.login(key=user_secrets.get_secret(\"WANDB_API_KEY\"))\n    except Exception as e:\n        print(f\"WandB login skipped/failed: {e}\")\n\n# ==========================================\n# 1. MEGASET DATASET LOADER (Agnostic naming)\n# ==========================================\nclass MashupMegasetDataset(Dataset):\n    def __init__(self, data_dirs, config, is_train=True):\n        self.files = []\n        for d in data_dirs:\n            if os.path.exists(d):\n                self.files.extend(glob.glob(f\"{d}/*/*.pt\"))\n            \n        self.is_train = is_train\n        self.target_frames = config[\"ast_frames\"]\n        \n        # Lighter masking to prevent underfitting\n        self.time_masking = T.TimeMasking(time_mask_param=50)\n        self.freq_masking = T.FrequencyMasking(freq_mask_param=12)\n\n    def __len__(self): return len(self.files)\n\n    def __getitem__(self, idx):\n        file_path = self.files[idx]\n        label = GENRE_TO_IDX[Path(file_path).parent.name]\n        mel_spec = torch.load(file_path).to(torch.float32)\n        \n        total_frames = mel_spec.shape[1]\n        if total_frames > self.target_frames:\n            if self.is_train:\n                start = random.randint(0, total_frames - self.target_frames)\n            else:\n                start = (total_frames - self.target_frames) // 2\n            mel_spec = mel_spec[:, start : start + self.target_frames]\n        else:\n            mel_spec = F.pad(mel_spec, (0, self.target_frames - total_frames))\n\n        # Shape becomes (1, 1024, 128)\n        mel_spec = mel_spec.transpose(0, 1).unsqueeze(0)\n\n        if self.is_train:\n            mel_spec = self.time_masking(mel_spec)\n            mel_spec = self.freq_masking(mel_spec)\n\n        return mel_spec, torch.tensor(label, dtype=torch.long)\n\n# ==========================================\n# 2. CUSTOM CNN ARCHITECTURE (From Scratch)\n# ==========================================\nclass MessyMashupCNN_Scratch(pl.LightningModule):\n    def __init__(self, config):\n        super().__init__()\n        self.save_hyperparameters(config)\n        self.config = config\n        \n        # Standard Deep CNN Architecture\n        # Input shape: (Batch, 1, 1024, 128)\n        self.features = nn.Sequential(\n            # Block 1\n            nn.Conv2d(1, 32, kernel_size=3, padding=1),\n            nn.BatchNorm2d(32),\n            nn.ReLU(),\n            nn.MaxPool2d(kernel_size=2, stride=2), \n\n            # Block 2\n            nn.Conv2d(32, 64, kernel_size=3, padding=1),\n            nn.BatchNorm2d(64),\n            nn.ReLU(),\n            nn.MaxPool2d(kernel_size=2, stride=2), \n\n            # Block 3\n            nn.Conv2d(64, 128, kernel_size=3, padding=1),\n            nn.BatchNorm2d(128),\n            nn.ReLU(),\n            nn.MaxPool2d(kernel_size=2, stride=2),\n\n            # Block 4\n            nn.Conv2d(128, 256, kernel_size=3, padding=1),\n            nn.BatchNorm2d(256),\n            nn.ReLU(),\n            nn.MaxPool2d(kernel_size=2, stride=2),\n\n            # Block 5\n            nn.Conv2d(256, 512, kernel_size=3, padding=1),\n            nn.BatchNorm2d(512),\n            nn.ReLU(),\n            \n            # Adaptive pool flattens any remaining spatial dimensions to 1x1 perfectly\n            nn.AdaptiveAvgPool2d((1, 1)) \n        )\n\n        self.classifier = nn.Sequential(\n            nn.Flatten(),\n            nn.Linear(512, 256),\n            nn.BatchNorm1d(256),\n            nn.ReLU(),\n            nn.Dropout(0.5), # Heavy dropout to prevent overfitting from scratch\n            nn.Linear(256, config[\"num_classes\"])\n        )\n\n        self.criterion = nn.CrossEntropyLoss(label_smoothing=config[\"label_smoothing\"])\n        self.train_f1 = MulticlassF1Score(num_classes=config[\"num_classes\"], average='macro')\n        self.val_f1 = MulticlassF1Score(num_classes=config[\"num_classes\"], average='macro')\n\n    def forward(self, x):\n        x = self.features(x)\n        return self.classifier(x)\n\n    def training_step(self, batch, batch_idx):\n        x, y = batch\n        \n        # Mixup Augmentation (Crucial for training from scratch)\n        if np.random.rand() < 0.2:\n            alpha = 0.2\n            lam = np.random.beta(alpha, alpha)\n            rand_index = torch.randperm(x.size()[0], device=x.device)\n            target_a, target_b = y, y[rand_index]\n            x = lam * x + (1 - lam) * x[rand_index]\n            logits = self(x)\n            loss = lam * self.criterion(logits, target_a) + (1 - lam) * self.criterion(logits, target_b)\n        else:\n            logits = self(x)\n            loss = self.criterion(logits, y)\n\n        preds = torch.argmax(logits, dim=1)\n        self.train_f1(preds, y)\n        self.log('train_loss', loss, prog_bar=True)\n        self.log('train_macro_f1', self.train_f1, on_epoch=True, prog_bar=True)\n        return loss\n\n    def validation_step(self, batch, batch_idx):\n        x, y = batch\n        logits = self(x)\n        preds = torch.argmax(logits, dim=1)\n        self.val_f1(preds, y)\n        self.log('val_loss', self.criterion(logits, y), prog_bar=True)\n        self.log('val_macro_f1', self.val_f1, prog_bar=True)\n\n    def configure_optimizers(self):\n        # Single learning rate for training from scratch\n        optimizer = torch.optim.AdamW(\n            self.parameters(), \n            lr=self.config[\"learning_rate\"], \n            weight_decay=self.config[\"weight_decay\"]\n        )\n        total_steps = self.trainer.estimated_stepping_batches\n        scheduler = get_cosine_schedule_with_warmup(\n            optimizer, num_warmup_steps=int(total_steps * 0.1), num_training_steps=total_steps\n        )\n        return {\"optimizer\": optimizer, \"lr_scheduler\": {\"scheduler\": scheduler, \"interval\": \"step\"}}\n\n    def load_best_weights(self, checkpoint_path):\n        print(f\"Loading weights from: {checkpoint_path}\")\n        # weights_only=False bypasses the PyTorch 2.6 Papermill crash\n        checkpoint = torch.load(checkpoint_path, map_location=lambda storage, loc: storage, weights_only=False)\n        state_dict = checkpoint['state_dict'] if 'state_dict' in checkpoint else checkpoint\n        \n        # Safely map weights to the architecture\n        model_dict = self.state_dict()\n        pretrained_dict = {k: v for k, v in state_dict.items() if k in model_dict and v.shape == model_dict[k].shape}\n        model_dict.update(pretrained_dict)\n        self.load_state_dict(model_dict)\n        print(\"✅ Successfully loaded weights.\")\n\n# ==========================================\n# 3. INFERENCE ENGINE (Test Time Augmentation)\n# ==========================================\ndef run_inference_tta(model, config):\n    print(\"--- RUNNING INFERENCE WITH TTA ---\")\n    device = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n    model = model.to(device)\n    model.eval()\n    \n    test_df = pd.read_csv(f\"{config['data_root']}/test.csv\")\n    predictions = []\n    \n    for _, row in tqdm(test_df.iterrows(), total=len(test_df)):\n        file_id = str(row['filename'])\n        if not file_id.endswith('.wav'):\n            file_id += '.wav'\n            \n        audio_path = os.path.join(config['data_root'], file_id)\n        \n        try:\n            y, _ = librosa.load(audio_path, sr=config[\"sample_rate\"])\n            mel_spec = librosa.feature.melspectrogram(y=y, sr=config[\"sample_rate\"], n_mels=128, n_fft=400, hop_length=160)\n            mel_spec_db = (librosa.power_to_db(mel_spec, ref=np.max) - AST_MEAN) / (AST_STD * 2)\n            tensor = torch.tensor(mel_spec_db, dtype=torch.float32)\n            \n            total_frames = tensor.shape[1]\n            frames = config[\"ast_frames\"]\n            \n            if total_frames > frames:\n                crop1 = tensor[:, 0 : frames]\n                crop2 = tensor[:, (total_frames - frames) // 2 : ((total_frames - frames) // 2) + frames]\n                crop3 = tensor[:, total_frames - frames : total_frames]\n                # Shape becomes (3, 1, 1024, 128) for the batch\n                batch = torch.stack([\n                    crop1.transpose(0, 1).unsqueeze(0), \n                    crop2.transpose(0, 1).unsqueeze(0), \n                    crop3.transpose(0, 1).unsqueeze(0)\n                ]).to(device)\n            else:\n                crop = F.pad(tensor, (0, frames - total_frames))\n                batch = crop.transpose(0, 1).unsqueeze(0).unsqueeze(0).to(device)\n\n            with torch.no_grad():\n                logits = model(batch)\n                avg_probs = torch.mean(F.softmax(logits, dim=1), dim=0)\n                pred_idx = torch.argmax(avg_probs).item()\n                predictions.append(IDX_TO_GENRE[pred_idx])\n                \n        except Exception as e:\n            print(f\"\\n❌ FATAL ERROR on {audio_path}: {e}\")\n            return\n            predictions.append(\"pop\") \n\n    test_df['genre'] = predictions\n    test_df[['id', 'genre']].to_csv('submission_cnn.csv', index=False)\n    print(\"✅ Saved predictions to submission_cnn.csv\")\n\n# ==========================================\n# 4. EXECUTION PIPELINE\n# ==========================================\nif __name__ == \"__main__\":\n\n    if RUN_TRAINING:\n        print(\"--- STARTING CNN SCRATCH TRAINING ---\")\n        \n        train_dirs = [\n            f\"{CONFIG['synthetic_data_dir']}/train\", \n            f\"{CONFIG['pseudo_labeled_dataset']}/train\",\n            f\"{CONFIG['pure_mashups_dir']}/train\"\n        ]\n        \n        val_dirs = [\n            f\"{CONFIG['synthetic_data_dir']}/val\",\n            f\"{CONFIG['pure_mashups_dir']}/val\"\n        ]\n        \n        train_ds = MashupMegasetDataset(train_dirs, CONFIG, is_train=True)\n        val_ds = MashupMegasetDataset(val_dirs, CONFIG, is_train=False)\n        \n        train_loader = DataLoader(train_ds, batch_size=CONFIG[\"batch_size\"], shuffle=True, num_workers=CONFIG[\"num_workers\"])\n        val_loader = DataLoader(val_ds, batch_size=CONFIG[\"batch_size\"], shuffle=False, num_workers=CONFIG[\"num_workers\"])\n        \n        print(f\"Total Megaset Training Chunks: {len(train_ds)}\")\n        print(f\"Total Validation Chunks: {len(val_ds)}\")\n        \n        model = MessyMashupCNN_Scratch(CONFIG)\n        \n        checkpoint_cb = ModelCheckpoint(\n            dirpath=\"checkpoints_cnn\", filename=\"best-cnn\", monitor=\"val_macro_f1\", mode=\"max\", save_top_k=1\n        )\n        early_stop_cb = EarlyStopping(monitor=\"val_macro_f1\", patience=CONFIG[\"patience\"], mode=\"max\", verbose=True)\n        swa_cb = StochasticWeightAveraging(swa_lrs=1e-4)\n        wandb_logger = WandbLogger(project=CONFIG[\"project_name\"], name=CONFIG[\"experiment_name\"])\n        \n        trainer = pl.Trainer(\n            max_epochs=CONFIG[\"num_epochs\"],\n            accelerator=\"gpu\",\n            devices=1,\n            logger=wandb_logger,\n            callbacks=[checkpoint_cb, early_stop_cb, swa_cb],\n            accumulate_grad_batches=CONFIG[\"accumulate_grad\"],\n            gradient_clip_val=1.0, \n            precision=\"16-mixed\",\n            deterministic=True\n        )\n        \n        trainer.fit(model, train_loader, val_loader)\n        \n    if RUN_INFERENCE:\n        local_ckpt = \"checkpoints_cnn/best-cnn.ckpt\"\n        dataset_ckpt = CONFIG.get(\"best_checkpoint\", \"\")\n        \n        if os.path.exists(local_ckpt):\n            print(f\"🚀 Loading freshly trained CNN checkpoint: {local_ckpt}\")\n            model = MessyMashupCNN_Scratch.load_from_checkpoint(local_ckpt)\n            \n        elif os.path.exists(dataset_ckpt):\n            print(f\"🚀 Loading Kaggle Dataset CNN checkpoint: {dataset_ckpt}\")\n            model = MessyMashupCNN_Scratch(CONFIG)\n            model.load_best_weights(dataset_ckpt)\n            \n        else:\n            print(\"🚨 NO CHECKPOINT FOUND! Initializing untrained CNN model. SCORE WILL BE RANDOM.\")\n            model = MessyMashupCNN_Scratch(CONFIG)\n            \n        run_inference_tta(model, CONFIG)\n\n# %% [code]\n","metadata":{"_uuid":"940720f1-5df7-4cce-beaf-29ff3651cda7","_cell_guid":"2464dc24-103d-4a19-b0ae-cf27829f517d","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}